FoamFile
{
    version     2.0;
    format      ascii;
    class       volScalarField;
    object      p.orig;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

dimensions      [1 -1 -2 0 0 0 0];

internalField   uniform 0.90530979e5;

boundaryField
{
    air_to_building
    {
        type            zeroGradient;
    }
    ground
    {
        type            zeroGradient;
    }
    outlet
    {
        type            pressureWaveTransmissive;
        value           $internalField;
    }
}

